export const BY_STORY = Object.fromEntries(STORIES.map((s) => [s.id, s]));

/** Every Persian line of a story that has a recording: sentences, poem lines, couplets, verses and hadith, the moral and the words. */
export function storyLines(story) {
  return [
    ...(story.sentences ?? []),
    ...(story.poem ?? []),
    ...(story.couplets ?? []),
    ...(story.quotes ?? []),
    ...(story.moral ? [story.moral] : []),
    ...story.words,
  ];
}
